# 28b  (B) joint bootstrap resampling installations instead of plots: each resample refits S1, then E4r and E6r with that resample's SDImax, as in 22t part 3.
source("scripts/28_common.R"); NB <- as.integer(Sys.getenv("KOA_NBOOT", "1000")); NC <- as.integer(Sys.getenv("KOA_CORES", "6")); RNGkind("L'Ecuyer-CMRG"); set.seed(20261114)
M2 <- M; ins <- unique(P$inst); iM <- split(seq_len(nrow(M2)), M2$inst); dI <- merge(d, P[, .(pid, inst)], by = "pid"); iD <- split(seq_len(nrow(dI)), dI$inst); iF <- split(seq_len(nrow(mfc)), mfc$inst)
cat("installations:", length(ins), "; with SDImax", length(iM), "; in the increment frame", length(iD), "; in the mortality frame", length(iF), "; resamples", NB, "\n")
res <- parallel::mclapply(seq_len(NB), function(i) tryCatch({ s <- sample(ins, length(ins), TRUE); b1 <- s1fit(M2[unlist(iM[s], use.names = FALSE)]); dd <- dI[unlist(iD[s], use.names = FALSE)]; g <- fitg(dd, bg, s1p(b1, dd$lbyi, dd$planted))
  m <- mfc[unlist(iF[s], use.names = FALSE)]; q <- mlfitG(Xmat(m, s1p(b1, m$lbyi, m$planted)), m$died, log(m$yip)); c(b1, g$b, q$b, gconv = g$conv, gmax = q$gmax) }, error = function(e) rep(NA_real_, 19)), mc.cores = NC)
R <- do.call(rbind, res); colnames(R) <- c(paste0("s1_", names(bs)), paste0("e4_", names(bg)), paste0("e6_", names(bm)), "gconv", "gmax"); ok <- complete.cases(R) & R[, "gmax"] < 1e-2 & apply(abs(R[, 1:17]), 1, max) < 50
cat("resamples: errors", sum(!complete.cases(R)), "; E6r gradient above 0.01:", sum(R[, "gmax"] >= 1e-2, na.rm = TRUE), "; kept", sum(ok), "\n"); KI <- R[ok, 1:17]; KP <- readRDS("out/rdbyi2_boot.rds")$K; est <- c(bs, bg, bm)
tab <- data.table(term = colnames(KI), estimate = signif(unname(est), 4), se_plot = signif(apply(KP, 2, sd), 3), se_inst = signif(apply(KI, 2, sd), 3), lo95_plot = signif(apply(KP, 2, quantile, .025), 3), hi95_plot = signif(apply(KP, 2, quantile, .975), 3), lo95_inst = signif(apply(KI, 2, quantile, .025), 3), hi95_inst = signif(apply(KI, 2, quantile, .975), 3)); tab[, se_ratio := round(se_inst / se_plot, 2)]; print(tab)
q <- function(x) paste(round(quantile(x, c(.025, .975)), 2), collapse = " to "); rr <- function(Kx, p) exp(Kx[, "e4_lbyi"] * (log(byiq[planted == p, hi]) - log(byiq[planted == p, lo])))
cat("\nheadline quantities, 95% interval: plot bootstrap | installation bootstrap\n")
cat("diameter growth, 90th over 10th percentile of BYI, natural:", round(exp(bg[["lbyi"]] * (log(byiq[planted == 0, hi]) - log(byiq[planted == 0, lo]))), 2), "|", q(rr(KP, 0)), "|", q(rr(KI, 0)), "\n")
cat("diameter growth, 90th over 10th percentile of BYI, planted:", round(exp(bg[["lbyi"]] * (log(byiq[planted == 1, hi]) - log(byiq[planted == 1, lo]))), 2), "|", q(rr(KP, 1)), "|", q(rr(KI, 1)), "\n")
cat("planted over natural diameter growth:", round(exp(bg[["pl"]]), 2), "|", q(exp(KP[, "e4_pl"])), "|", q(exp(KI[, "e4_pl"])), "\n"); cat("planted over natural mortality hazard:", round(exp(bm[["planted"]]), 2), "|", q(exp(KP[, "e6_planted"])), "|", q(exp(KI[, "e6_planted"])), "\n")
cat("planted over natural SDImax:", round(exp(bs[[3]]), 2), "|", q(exp(KP[, 3])), "|", q(exp(KI[, 3])), "\n"); cat("S1 ln(BYI):", round(bs[[2]], 3), "|", q(KP[, 2]), "|", q(KI[, 2]), "\n")
cat("share of kept installation resamples with: positive ln(BYI) in E4r", round(mean(KI[, "e4_lbyi"] > 0), 4), "; positive ln(BYI) in S1", round(mean(KI[, "s1_lbyi"] > 0), 4), "; positive ln(RD) in E6r", round(mean(KI[, "e6_lrd"] > 0), 4), "; negative competition term in E4r", round(mean(KI[, "e4_xrd"] < 0), 4), "; planted hazard below natural", round(mean(KI[, "e6_planted"] < 0), 4), "; positive DBH-squared in E6r", round(mean(KI[, "e6_I(dbh_m^2)"] > 0), 4), "\n")
saveRDS(list(K = KI, n = NB, kept = sum(ok)), "out/check28b_instboot.rds"); cat("28b done\n")
